-- PC-AC 2026: matriz oficial do cargo Oficial Investigador de Polícia.
-- Fonte: Edital nº 001/2026 – SEAD/PCAC, publicado no DOE/AC em 06/11/2026.
-- Sem ON CONFLICT: produção mostrou tabelas sem a unique constraint do schema
-- em pelo menos um caso (contest_reference_info); update + insert condicional
-- (not exists) funciona independente disso.

-- Oficial Investigador de Polícia
update public.content_sources set title='Edital nº 001/2026 – SEAD/PCAC – Oficial Investigador de Polícia', issuer='Secretaria de Estado de Administração / Polícia Civil do Estado do Acre / IDECAN', published_on='2026-11-06', status='vigente', notes='Edital oficial. 74 vagas, distribuídas por município conforme o edital. Remuneração: R$ 6.342,07.', checked_at=now()
where url='https://www.diario.ac.gov.br/#pcac-2026-investigador';

insert into public.content_sources (source_type, title, issuer, url, published_on, status, notes)
select 'edital','Edital nº 001/2026 – SEAD/PCAC – Oficial Investigador de Polícia','Secretaria de Estado de Administração / Polícia Civil do Estado do Acre / IDECAN','https://www.diario.ac.gov.br/#pcac-2026-investigador','2026-11-06','vigente','Edital oficial. 74 vagas, distribuídas por município conforme o edital. Remuneração: R$ 6.342,07.'
where not exists (select 1 from public.content_sources where url='https://www.diario.ac.gov.br/#pcac-2026-investigador');

update public.syllabus_editions set source_id=(select id from public.content_sources where url='https://www.diario.ac.gov.br/#pcac-2026-investigador'), exam_board='IDECAN', status='active'
where contest_name='Polícia Civil do Acre' and role_name='Oficial Investigador de Polícia' and contest_year=2026;

insert into public.syllabus_editions (contest_name, role_name, contest_year, exam_board, source_id, status)
select 'Polícia Civil do Acre', 'Oficial Investigador de Polícia', 2026, 'IDECAN', id, 'active'
from public.content_sources where url='https://www.diario.ac.gov.br/#pcac-2026-investigador'
and not exists (
  select 1 from public.syllabus_editions where contest_name='Polícia Civil do Acre' and role_name='Oficial Investigador de Polícia' and contest_year=2026
);

with edition as (
  select id from public.syllabus_editions where contest_name='Polícia Civil do Acre' and role_name='Oficial Investigador de Polícia' and contest_year=2026
),
topics(block_name, discipline, topic_order, topic_text) as (values
  ('Conhecimentos básicos', 'Língua Portuguesa', 1, 'Leitura, compreensão e interpretação de textos: gêneros variados, incluindo textos argumentativos, normativos, científicos e jornalísticos; análise crítica e inferencial. Estruturação do texto e dos parágrafos: organização, progressão e hierarquia das ideias. Articulação textual: pronomes e expressões referenciais, nexos, operadores sequenciais e conectivos. Coesão e coerência textual: mecanismos de coesão referencial, lexical e sequencial. Reescrita de frases: equivalência e transformação de estruturas; paralelismo sintático e semântico. Significação contextual de palavras e expressões: sinonímia, antonímia, polissemia, ambiguidade e denotação/conotação. Norma-padrão da língua portuguesa: ortografia oficial, acentuação gráfica e pontuação. Morfologia, estrutura e formação de palavras. Emprego das classes de palavras. Sintaxe e construção frasal: análise sintática dos termos da oração e do período simples e composto (coordenação e subordinação). Concordância verbal e nominal. Regência verbal e nominal. Colocação pronominal. Crase. Variação linguística e adequação da linguagem. Figuras de linguagem. Linguagem e tecnologia: gêneros digitais, comunicação em ambientes virtuais e inteligência artificial aplicada à linguagem.'),
  ('Conhecimentos básicos', 'Raciocínio Lógico', 2, 'Raciocínio lógico numérico: Resolução de problemas envolvendo números reais. Estruturas lógicas: proposições simples e compostas. Conectivos lógicos: conjunção, disjunção, condicional e bicondicional. Tabelas-verdade. Equivalências lógicas. Negação de proposições. Argumentação lógica: validade de argumentos. Verdades e mentiras. Sequências e padrões: sequências numéricas e identificação de padrões. Progressões aritmética e geométrica. Relações de ordem e equivalência. Problemas com conjuntos. Porcentagem. Juros simples e compostos. Análise combinatória. Probabilidade da união de dois eventos. Probabilidade condicional. Probabilidade de eventos independentes. Média aritmética simples e ponderada. Raciocínio lógico quantitativo: porcentagem, razão e proporção, regra de três simples e composta. Interpretação de gráficos e tabelas.'),
  ('Conhecimentos básicos', 'Noções de Informática', 3, 'Fundamentos de sistemas computacionais: Hardware, software e formatos de arquivo; formatos abertos e proprietários; interoperabilidade. Armazenamento local, remoto e em nuvem; sincronização e controle de versões. Software livre, licenciamento e acessibilidade digital. Sistemas operacionais em ambiente corporativo (Windows 11 e Linux Ubuntu). – Arquivos, pastas e permissões; contas de usuário e perfis de acesso. Histórico de versões e recuperação de arquivos. Atualizações, privacidade e segurança. Editores de texto (Microsoft Word e LibreOffice Writer). – Estilos e estruturação de documentos extensos; sumário automático, notas, legendas e referências cruzadas. – Mala direta e modelos. Comentários, controle de alterações e comparação de documentos. – Proteção de documentos e exportação para PDF. Planilhas eletrônicas (Microsoft Excel e LibreOffice Calc). – Fórmulas, referências e funções matemáticas, estatísticas, lógicas, de texto, de data/hora e de pesquisa. Classificação, filtros e validação de dados. Formatação condicional, tabelas dinâmicas e gráficos. Proteção de dados e identificação de erros. Apresentações e integração entre aplicativos: Slide mestre, temas, transições, animações e modo apresentador (PowerPoint e Impress). Transferência de dados entre texto, planilha e apresentação; incorporação e vinculação de objetos. Compatibilidade entre pacotes e versões; conversão para PDF. Internet, intranet e pesquisa (Chrome, Edge e Firefox). Internet, intranet, extranet e protocolos básicos. HTTPS e certificados digitais. Estratégias e operadores de busca; avaliação de fontes; desinformação e conteúdos manipulados. Correio eletrônico corporativo (Outlook, Thunderbird e Gmail): Protocolos SMTP, POP3 e IMAP; webmail e clientes de e-mail. Listas de distribuição, regras, calendários e convites. Phishing e variações, falsificação de remetente e cuidados com dados sigilosos. Computação em nuvem e trabalho colaborativo (Microsoft 365, Google Workspace, Teams, Meet e Zoom): Compartilhamento por usuários, grupos e links; permissões, coautoria e histórico de versões. Transferência e revogação de acesso; riscos de links públicos e permissões excessivas. Fundamentos de sistemas de informação: Dado, informação e conhecimento; conceitos básicos de banco de dados e qualidade dos dados. Autenticação, autorização e auditoria. Segregação de funções, princípio do menor privilégio, trilhas de auditoria e disponibilidade. Sistemas aplicados à Administração Pública: Publicidade e transparência ativa e passiva. Informações públicas, sigilosas e classificadas; restrição de acesso e necessidade de conhecimento. Proteção de dados pessoais em documentos públicos; cuidados na publicação e no compartilhamento de documentos digitais.'),
  ('Conhecimentos básicos', 'Realidade do Acre (étnica, social, geográfica, cultural, política e econômica)', 4, 'Formação histórica do Acre: ocupação, ciclos da borracha, antecedentes diplomáticos (Tratado de Ayacucho), Revolução Acreana, Tratado de Petrópolis, Território Federal, movimento autonomista e elevação a Estado. Movimento dos seringueiros, Chico Mendes e criação das reservas extrativistas. Geografia: localização, limites e fronteiras, fuso horário, municípios e regionais de desenvolvimento, bacias hidrográficas, relevo, clima, vegetação e unidades de conservação. Aspectos étnicos e culturais: povos indígenas, incluindo povos isolados, populações tradicionais, extrativismo e manifestações culturais. Aspectos políticos: Constituição do Estado do Acre, organização dos Poderes e símbolos estaduais. Aspectos sociais e econômicos: população e indicadores sociais, economia, produção extrativista e agropecuária, desenvolvimento sustentável, infraestrutura de transportes e integração regional e fronteiriça. Segurança pública no Acre: estrutura do sistema estadual de segurança pública e aspectos das regiões de fronteira.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Constitucional', 1, 'Princípios fundamentais. Direitos e garantias fundamentais: direitos e deveres individuais e coletivos; remédios constitucionais. Administração Pública: disposições gerais e servidores públicos (arts. 37 a 41 da Constituição Federal). Segurança pública (art. 144 da Constituição Federal). Constituição do Estado do Acre: disposições sobre segurança pública e Polícia Civil.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Penal e Processual Penal', 2, 'Aplicação da lei penal. Crime: conceito, tipicidade, ilicitude e culpabilidade; consumação e tentativa; concurso de pessoas. Crimes contra a pessoa. Crimes contra o patrimônio. Crimes contra a dignidade sexual. Crimes contra o respeito aos mortos (arts. 209 a 212 do Código Penal). Crimes contra a fé pública: falsidade documental e falsa identidade (arts. 296 a 311 do Código Penal). Crimes contra a administração pública, crimes praticados por funcionário público (arts. 312 a 327 do Código Penal); falso testemunho ou falsa perícia (art. 342) e fraude processual (art. 347). Tortura (Lei nº 9.455/1997). Abuso de autoridade (Lei nº 13.869/2019). Inquérito policial (arts. 4º a 23 do Código de Processo Penal). Prova: disposições gerais, exame de corpo de delito, cadeia de custódia e perícias em geral (arts. 155 a 184 do Código de Processo Penal). Peritos e intérpretes (arts. 275 a 281 do Código de Processo Penal). Identificação criminal (Lei nº 12.037/2009). Prisão em flagrante, preventiva e temporária; medidas cautelares diversas da prisão.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Administrativo', 3, 'Princípios da Administração Pública. Organização administrativa: administração direta e indireta; centralização, descentralização e desconcentração. Poderes administrativos; poder de polícia; polícia administrativa e polícia judiciária. Atos administrativos. Agentes públicos. Responsabilidade civil do Estado. Improbidade administrativa (Lei nº 8.429/1992 com as alterações da Lei nº 14.230/2021).'),
  ('Conhecimentos jurídicos (noções)', 'Legislação Institucional', 4, 'Lei Federal nº 14.735/2023 (Lei Orgânica Nacional das Polícias Civis). Lei Complementar Estadual nº 129/2004 e alterações (Lei Orgânica da Polícia Civil do Estado do Acre). Lei Estadual nº 2.250/2009 e alterações (Plano de Cargos, Carreiras e Remuneração da Polícia Civil do Estado do Acre). Lei Complementar Estadual nº 39/1993 e alterações (Estatuto dos Servidores Públicos Civis do Estado do Acre), nos dispositivos aplicáveis: direitos, deveres e regime disciplinar.'),
  ('Conhecimentos específicos', 'Contabilidade Geral e Análise Financeira', 1, 'Conceitos fundamentais de contabilidade. 1.1 Objeto, finalidade e campo de aplicação. 1.2 Patrimônio e seus componentes. 1.3 Ativo, passivo e patrimônio líquido. 1.4 Equação fundamental do patrimônio. Contas contábeis. 2.1 Contas patrimoniais e de resultado. 2.2 Receitas, despesas, custos e resultados. 2.3 Fatos contábeis e suas classificações. Escrituração contábil. 3.1 Método das partidas dobradas. 3.2 Lançamentos contábeis. 3.3 Livros contábeis. 3.4 Balancete de verificação. Demonstrações contábeis. 4.1 Balanço patrimonial. 4.2 Demonstração do Resultado do Exercício. 4.3 Regimes de caixa e de competência. 4.4 Interpretação básica de demonstrações contábeis. Matemática financeira. 5.1 Juros simples e compostos. 5.2 Taxas de juros. 5.3 Descontos e atualização de valores. 5.4 Cálculos percentuais aplicados a operações financeiras. Sistema bancário e operações financeiras. 6.1 Estrutura e interpretação de extratos bancários. 6.2 Créditos, débitos e saldos. 6.3 Depósitos, saques, pagamentos e transferências. 6.4 Operações PIX e TED. 6.5 Identificação de contas de origem e destino de recursos. Análise de movimentações financeiras. 7.1 Organização de transações por data, valor, origem e destino. 7.2 Conciliação de movimentações financeiras. 7.3 Identificação de transferências recorrentes, fracionadas ou concentradas. 7.4 Análise de entradas e saídas de recursos. 7.5 Identificação de movimentações atípicas e inconsistências financeiras. 7.6 Cruzamento de informações financeiras. 7.7 Elaboração de demonstrativos financeiros simplificados. 7.8 Interpretação de fluxos financeiros e relações entre transações.'),
  ('Conhecimentos específicos', 'Estatística', 2, 'Conceitos fundamentais de estatística. 1.1 Estatística descritiva e inferencial. 1.2 População e amostra. 1.3 Técnicas básicas de amostragem. 1.4 Variáveis qualitativas e quantitativas. Organização e apresentação de dados. 2.1 Distribuição de frequências. 2.2 Frequências absolutas, relativas e acumuladas. 2.3 Construção e interpretação de tabelas. 2.4 Representações gráficas: gráficos de barras, linhas, setores e histogramas. Medidas de tendência central. 3.1 Média aritmética simples e ponderada. 3.2 Mediana. 3.3 Moda. Medidas de dispersão. 4.1 Amplitude. 4.2 Variância. 4.3 Desvio-padrão. 4.4 Coeficiente de variação. Medidas de posição. 5.1 Quartis. 5.2 Decis. 5.3 Percentis. Probabilidade. 6.1 Conceitos fundamentais. 6.2 Eventos e espaço amostral. 6.3 Probabilidade condicional. 6.4 Independência de eventos. 6.5 Noções de distribuições de probabilidade. Análise de relações entre variáveis. 7.1 Correlação. 7.2 Noções de regressão linear simples. 7.3 Distinção entre correlação e causalidade. Análise de séries temporais. 8.1 Identificação de padrões e tendências. 8.2 Variações e comparações entre períodos. Análise e interpretação de dados. 9.1 Identificação de valores discrepantes (outliers). 9.2 Interpretação de indicadores estatísticos. 9.3 Comparação entre conjuntos de dados. 9.4 Limitações e possíveis erros na interpretação estatística.'),
  ('Conhecimentos específicos', 'Arquivologia', 3, 'Conceitos fundamentais de arquivologia. 1.1 Natureza, finalidade e funções dos arquivos. 1.2 Princípios arquivísticos. 1.3 Classificação dos documentos quanto à natureza, espécie, gênero e suporte. Ciclo de vida dos documentos. 2.1 Teoria das três idades. 2.2 Arquivos correntes, intermediários e permanentes. Gestão documental. 3.1 Produção, recebimento, registro e tramitação de documentos. 3.2 Protocolo e controle documental. 3.3 Classificação e organização de documentos. 3.4 Métodos de arquivamento. 3.5 Avaliação e destinação documental. 3.6 Tabelas de temporalidade. Preservação e conservação de documentos. 4.1 Acondicionamento e armazenamento. 4.2 Medidas preventivas de conservação. Documentos digitais. 5.1 Conceitos e características. 5.2 Digitalização de documentos. 5.3 Sistemas informatizados de gestão arquivística de documentos. 5.4 Metadados e indexação documental. 5.5 Autenticidade, integridade e confiabilidade dos documentos. 5.6 Controle de versões e rastreabilidade documental. Gestão da informação arquivística. 6.1 Organização de acervos físicos e digitais. 6.2 Recuperação e localização de informações. 6.3 Controle de acesso a documentos. 6.4 Proteção de documentos sigilosos. 6.5 Compartilhamento e disponibilização de informações.'),
  ('Conhecimentos específicos', 'Tecnologia da Informação e Segurança da Informação', 4, 'Conceitos fundamentais de tecnologia da informação. 1.1 Sistemas de informação. 1.2 Processamento, armazenamento e transmissão de dados. 1.3 Dados estruturados e não estruturados. Sistemas operacionais e aplicativos. 2.1 Gerenciamento de arquivos e diretórios. 2.2 Formatos de arquivos digitais. 2.3 Compactação e descompactação de arquivos. Planilhas eletrônicas aplicadas à análise de dados. 3.1 Fórmulas e funções básicas e intermediárias. 3.2 Classificação, filtros e agrupamentos. 3.3 Tabelas dinâmicas e gráficos. 3.4 Importação e exportação de dados. 3.5 Tratamento de dados duplicados ou inconsistentes. Bancos de dados. 4.1 Conceitos fundamentais. 4.2 Tabelas, registros, campos, chaves e relacionamentos. 4.3 Consultas e filtros de dados. 4.4 Integração básica de informações provenientes de diferentes bases. Redes de computadores. 5.1 Conceitos de redes locais e internet. 5.2 Endereçamento IP. 5.3 Protocolos de comunicação. 5.4 Serviços de rede. Segurança da informação. 6.1 Confidencialidade, integridade e disponibilidade. 6.2 Controle de acesso e autenticação. 6.3 Criptografia: conceitos fundamentais. 6.4 Cópias de segurança. 6.5 Proteção de informações sensíveis. Metadados. 7.1 Conceitos e características. 7.2 Propriedades de arquivos digitais. 7.3 Informações de criação, modificação e armazenamento. Organização e tratamento de informações digitais. 8.1 Padronização e classificação de registros. 8.2 Identificação de duplicidades. 8.3 Cruzamento de informações em planilhas. 8.4 Construção de tabelas e gráficos para apresentação de resultados.'),
  ('Conhecimentos específicos', 'Análise de Dados e Informações', 5, 'Conceitos fundamentais de dados, informação e conhecimento. 1.1 Dados estruturados, semiestruturados e não estruturados. 1.2 Fontes de informação. 1.3 Critérios de confiabilidade e qualidade das informações. Organização e tratamento de dados. 2.1 Coleta e classificação de informações. 2.2 Padronização de registros. 2.3 Identificação de duplicidades e inconsistências. 2.4 Tratamento de dados incompletos. 2.5 Organização de conjuntos de dados em tabelas e planilhas. Cruzamento e comparação de informações. 3.1 Identificação de correspondências entre registros. 3.2 Comparação de dados provenientes de diferentes fontes. 3.3 Identificação de padrões, recorrências e divergências. 3.4 Análise de relações entre registros. Análise temporal. 4.1 Organização cronológica de eventos. 4.2 Construção e interpretação de linhas do tempo. 4.3 Identificação de intervalos e sequências temporais. 4.4 Comparação de registros por data e horário. Análise de vínculos. 5.1 Identificação de relações entre pessoas, organizações, endereços e registros. 5.2 Construção e interpretação de diagramas de vínculos. 5.3 Identificação de conexões diretas e indiretas. 5.4 Análise de redes de relacionamento em conjuntos de dados. Análise de registros de comunicação. 6.1 Organização de registros em tabelas. 6.2 Identificação de frequência, duração e sequência de comunicações. 6.3 Comparação de registros de contatos e horários. 6.4 Identificação de padrões de comunicação. Análise geográfica básica. 7.1 Localização e distribuição espacial de eventos. 7.2 Interpretação de coordenadas geográficas. 7.3 Comparação de distâncias e trajetos. 7.4 Representação de informações em mapas. Métodos de análise de informações. 8.1 Identificação de fatos, inferências e hipóteses. 8.2 Formulação e comparação de hipóteses explicativas. 8.3 Identificação de contradições e lacunas informacionais. 8.4 Avaliação da consistência de informações. 8.5 Distinção entre correlação e causalidade. Produção de informações analíticas. 9.1 Elaboração de quadros demonstrativos. 9.2 Construção de tabelas, gráficos e diagramas. 9.3 Sistematização e síntese de informações. 9.4 Elaboração de relatórios informativos e analíticos. 9.5 Apresentação objetiva de resultados e conclusões. 9.6 Indicação de limitações e insuficiências dos dados analisados. Proteção e qualidade das informações. 10.1 Confidencialidade e controle de acesso. 10.2 Integridade e rastreabilidade de registros. 10.3 Identificação de erros e inconsistências em bases de dados.'),
  ('Conhecimentos específicos', 'Noções de Administração', 6, 'Conceitos e princípios gerais da administração. 1.1 Funções administrativas: planejamento, organização, direção e controle. 1.2 Eficiência, eficácia e efetividade. Estruturas organizacionais. 2.1 Organização e divisão do trabalho. 2.2 Comunicação organizacional. 2.3 Trabalho em equipe e relações interpessoais. Gestão de processos. 3.1 Organização e padronização de rotinas de trabalho. 3.2 Planejamento e controle de atividades. 3.3 Gestão do tempo e definição de prioridades. 3.4 Melhoria contínua de processos. Gestão da informação e do conhecimento. 4.1 Organização, armazenamento e compartilhamento de informações. 4.2 Fluxos de informação nas organizações. 4.3 Gestão de documentos e registros administrativos. Administração de recursos materiais. 5.1 Controle e organização de materiais. 5.2 Noções de gestão patrimonial. Qualidade no atendimento. 6.1 Atendimento ao público. 6.2 Comunicação clara e objetiva. 6.3 Ética e comportamento profissional. 6.4 Responsabilidade e sigilo no tratamento de informações.')
)
update public.syllabus_topics t set block_name=topics.block_name, topic_text=topics.topic_text, content_status='current'
from edition, topics
where t.edition_id=edition.id and t.discipline=topics.discipline and t.topic_order=topics.topic_order;

with edition as (
  select id from public.syllabus_editions where contest_name='Polícia Civil do Acre' and role_name='Oficial Investigador de Polícia' and contest_year=2026
),
topics(block_name, discipline, topic_order, topic_text) as (values
  ('Conhecimentos básicos', 'Língua Portuguesa', 1, 'Leitura, compreensão e interpretação de textos: gêneros variados, incluindo textos argumentativos, normativos, científicos e jornalísticos; análise crítica e inferencial. Estruturação do texto e dos parágrafos: organização, progressão e hierarquia das ideias. Articulação textual: pronomes e expressões referenciais, nexos, operadores sequenciais e conectivos. Coesão e coerência textual: mecanismos de coesão referencial, lexical e sequencial. Reescrita de frases: equivalência e transformação de estruturas; paralelismo sintático e semântico. Significação contextual de palavras e expressões: sinonímia, antonímia, polissemia, ambiguidade e denotação/conotação. Norma-padrão da língua portuguesa: ortografia oficial, acentuação gráfica e pontuação. Morfologia, estrutura e formação de palavras. Emprego das classes de palavras. Sintaxe e construção frasal: análise sintática dos termos da oração e do período simples e composto (coordenação e subordinação). Concordância verbal e nominal. Regência verbal e nominal. Colocação pronominal. Crase. Variação linguística e adequação da linguagem. Figuras de linguagem. Linguagem e tecnologia: gêneros digitais, comunicação em ambientes virtuais e inteligência artificial aplicada à linguagem.'),
  ('Conhecimentos básicos', 'Raciocínio Lógico', 2, 'Raciocínio lógico numérico: Resolução de problemas envolvendo números reais. Estruturas lógicas: proposições simples e compostas. Conectivos lógicos: conjunção, disjunção, condicional e bicondicional. Tabelas-verdade. Equivalências lógicas. Negação de proposições. Argumentação lógica: validade de argumentos. Verdades e mentiras. Sequências e padrões: sequências numéricas e identificação de padrões. Progressões aritmética e geométrica. Relações de ordem e equivalência. Problemas com conjuntos. Porcentagem. Juros simples e compostos. Análise combinatória. Probabilidade da união de dois eventos. Probabilidade condicional. Probabilidade de eventos independentes. Média aritmética simples e ponderada. Raciocínio lógico quantitativo: porcentagem, razão e proporção, regra de três simples e composta. Interpretação de gráficos e tabelas.'),
  ('Conhecimentos básicos', 'Noções de Informática', 3, 'Fundamentos de sistemas computacionais: Hardware, software e formatos de arquivo; formatos abertos e proprietários; interoperabilidade. Armazenamento local, remoto e em nuvem; sincronização e controle de versões. Software livre, licenciamento e acessibilidade digital. Sistemas operacionais em ambiente corporativo (Windows 11 e Linux Ubuntu). – Arquivos, pastas e permissões; contas de usuário e perfis de acesso. Histórico de versões e recuperação de arquivos. Atualizações, privacidade e segurança. Editores de texto (Microsoft Word e LibreOffice Writer). – Estilos e estruturação de documentos extensos; sumário automático, notas, legendas e referências cruzadas. – Mala direta e modelos. Comentários, controle de alterações e comparação de documentos. – Proteção de documentos e exportação para PDF. Planilhas eletrônicas (Microsoft Excel e LibreOffice Calc). – Fórmulas, referências e funções matemáticas, estatísticas, lógicas, de texto, de data/hora e de pesquisa. Classificação, filtros e validação de dados. Formatação condicional, tabelas dinâmicas e gráficos. Proteção de dados e identificação de erros. Apresentações e integração entre aplicativos: Slide mestre, temas, transições, animações e modo apresentador (PowerPoint e Impress). Transferência de dados entre texto, planilha e apresentação; incorporação e vinculação de objetos. Compatibilidade entre pacotes e versões; conversão para PDF. Internet, intranet e pesquisa (Chrome, Edge e Firefox). Internet, intranet, extranet e protocolos básicos. HTTPS e certificados digitais. Estratégias e operadores de busca; avaliação de fontes; desinformação e conteúdos manipulados. Correio eletrônico corporativo (Outlook, Thunderbird e Gmail): Protocolos SMTP, POP3 e IMAP; webmail e clientes de e-mail. Listas de distribuição, regras, calendários e convites. Phishing e variações, falsificação de remetente e cuidados com dados sigilosos. Computação em nuvem e trabalho colaborativo (Microsoft 365, Google Workspace, Teams, Meet e Zoom): Compartilhamento por usuários, grupos e links; permissões, coautoria e histórico de versões. Transferência e revogação de acesso; riscos de links públicos e permissões excessivas. Fundamentos de sistemas de informação: Dado, informação e conhecimento; conceitos básicos de banco de dados e qualidade dos dados. Autenticação, autorização e auditoria. Segregação de funções, princípio do menor privilégio, trilhas de auditoria e disponibilidade. Sistemas aplicados à Administração Pública: Publicidade e transparência ativa e passiva. Informações públicas, sigilosas e classificadas; restrição de acesso e necessidade de conhecimento. Proteção de dados pessoais em documentos públicos; cuidados na publicação e no compartilhamento de documentos digitais.'),
  ('Conhecimentos básicos', 'Realidade do Acre (étnica, social, geográfica, cultural, política e econômica)', 4, 'Formação histórica do Acre: ocupação, ciclos da borracha, antecedentes diplomáticos (Tratado de Ayacucho), Revolução Acreana, Tratado de Petrópolis, Território Federal, movimento autonomista e elevação a Estado. Movimento dos seringueiros, Chico Mendes e criação das reservas extrativistas. Geografia: localização, limites e fronteiras, fuso horário, municípios e regionais de desenvolvimento, bacias hidrográficas, relevo, clima, vegetação e unidades de conservação. Aspectos étnicos e culturais: povos indígenas, incluindo povos isolados, populações tradicionais, extrativismo e manifestações culturais. Aspectos políticos: Constituição do Estado do Acre, organização dos Poderes e símbolos estaduais. Aspectos sociais e econômicos: população e indicadores sociais, economia, produção extrativista e agropecuária, desenvolvimento sustentável, infraestrutura de transportes e integração regional e fronteiriça. Segurança pública no Acre: estrutura do sistema estadual de segurança pública e aspectos das regiões de fronteira.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Constitucional', 1, 'Princípios fundamentais. Direitos e garantias fundamentais: direitos e deveres individuais e coletivos; remédios constitucionais. Administração Pública: disposições gerais e servidores públicos (arts. 37 a 41 da Constituição Federal). Segurança pública (art. 144 da Constituição Federal). Constituição do Estado do Acre: disposições sobre segurança pública e Polícia Civil.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Penal e Processual Penal', 2, 'Aplicação da lei penal. Crime: conceito, tipicidade, ilicitude e culpabilidade; consumação e tentativa; concurso de pessoas. Crimes contra a pessoa. Crimes contra o patrimônio. Crimes contra a dignidade sexual. Crimes contra o respeito aos mortos (arts. 209 a 212 do Código Penal). Crimes contra a fé pública: falsidade documental e falsa identidade (arts. 296 a 311 do Código Penal). Crimes contra a administração pública, crimes praticados por funcionário público (arts. 312 a 327 do Código Penal); falso testemunho ou falsa perícia (art. 342) e fraude processual (art. 347). Tortura (Lei nº 9.455/1997). Abuso de autoridade (Lei nº 13.869/2019). Inquérito policial (arts. 4º a 23 do Código de Processo Penal). Prova: disposições gerais, exame de corpo de delito, cadeia de custódia e perícias em geral (arts. 155 a 184 do Código de Processo Penal). Peritos e intérpretes (arts. 275 a 281 do Código de Processo Penal). Identificação criminal (Lei nº 12.037/2009). Prisão em flagrante, preventiva e temporária; medidas cautelares diversas da prisão.'),
  ('Conhecimentos jurídicos (noções)', 'Noções de Direito Administrativo', 3, 'Princípios da Administração Pública. Organização administrativa: administração direta e indireta; centralização, descentralização e desconcentração. Poderes administrativos; poder de polícia; polícia administrativa e polícia judiciária. Atos administrativos. Agentes públicos. Responsabilidade civil do Estado. Improbidade administrativa (Lei nº 8.429/1992 com as alterações da Lei nº 14.230/2021).'),
  ('Conhecimentos jurídicos (noções)', 'Legislação Institucional', 4, 'Lei Federal nº 14.735/2023 (Lei Orgânica Nacional das Polícias Civis). Lei Complementar Estadual nº 129/2004 e alterações (Lei Orgânica da Polícia Civil do Estado do Acre). Lei Estadual nº 2.250/2009 e alterações (Plano de Cargos, Carreiras e Remuneração da Polícia Civil do Estado do Acre). Lei Complementar Estadual nº 39/1993 e alterações (Estatuto dos Servidores Públicos Civis do Estado do Acre), nos dispositivos aplicáveis: direitos, deveres e regime disciplinar.'),
  ('Conhecimentos específicos', 'Contabilidade Geral e Análise Financeira', 1, 'Conceitos fundamentais de contabilidade. 1.1 Objeto, finalidade e campo de aplicação. 1.2 Patrimônio e seus componentes. 1.3 Ativo, passivo e patrimônio líquido. 1.4 Equação fundamental do patrimônio. Contas contábeis. 2.1 Contas patrimoniais e de resultado. 2.2 Receitas, despesas, custos e resultados. 2.3 Fatos contábeis e suas classificações. Escrituração contábil. 3.1 Método das partidas dobradas. 3.2 Lançamentos contábeis. 3.3 Livros contábeis. 3.4 Balancete de verificação. Demonstrações contábeis. 4.1 Balanço patrimonial. 4.2 Demonstração do Resultado do Exercício. 4.3 Regimes de caixa e de competência. 4.4 Interpretação básica de demonstrações contábeis. Matemática financeira. 5.1 Juros simples e compostos. 5.2 Taxas de juros. 5.3 Descontos e atualização de valores. 5.4 Cálculos percentuais aplicados a operações financeiras. Sistema bancário e operações financeiras. 6.1 Estrutura e interpretação de extratos bancários. 6.2 Créditos, débitos e saldos. 6.3 Depósitos, saques, pagamentos e transferências. 6.4 Operações PIX e TED. 6.5 Identificação de contas de origem e destino de recursos. Análise de movimentações financeiras. 7.1 Organização de transações por data, valor, origem e destino. 7.2 Conciliação de movimentações financeiras. 7.3 Identificação de transferências recorrentes, fracionadas ou concentradas. 7.4 Análise de entradas e saídas de recursos. 7.5 Identificação de movimentações atípicas e inconsistências financeiras. 7.6 Cruzamento de informações financeiras. 7.7 Elaboração de demonstrativos financeiros simplificados. 7.8 Interpretação de fluxos financeiros e relações entre transações.'),
  ('Conhecimentos específicos', 'Estatística', 2, 'Conceitos fundamentais de estatística. 1.1 Estatística descritiva e inferencial. 1.2 População e amostra. 1.3 Técnicas básicas de amostragem. 1.4 Variáveis qualitativas e quantitativas. Organização e apresentação de dados. 2.1 Distribuição de frequências. 2.2 Frequências absolutas, relativas e acumuladas. 2.3 Construção e interpretação de tabelas. 2.4 Representações gráficas: gráficos de barras, linhas, setores e histogramas. Medidas de tendência central. 3.1 Média aritmética simples e ponderada. 3.2 Mediana. 3.3 Moda. Medidas de dispersão. 4.1 Amplitude. 4.2 Variância. 4.3 Desvio-padrão. 4.4 Coeficiente de variação. Medidas de posição. 5.1 Quartis. 5.2 Decis. 5.3 Percentis. Probabilidade. 6.1 Conceitos fundamentais. 6.2 Eventos e espaço amostral. 6.3 Probabilidade condicional. 6.4 Independência de eventos. 6.5 Noções de distribuições de probabilidade. Análise de relações entre variáveis. 7.1 Correlação. 7.2 Noções de regressão linear simples. 7.3 Distinção entre correlação e causalidade. Análise de séries temporais. 8.1 Identificação de padrões e tendências. 8.2 Variações e comparações entre períodos. Análise e interpretação de dados. 9.1 Identificação de valores discrepantes (outliers). 9.2 Interpretação de indicadores estatísticos. 9.3 Comparação entre conjuntos de dados. 9.4 Limitações e possíveis erros na interpretação estatística.'),
  ('Conhecimentos específicos', 'Arquivologia', 3, 'Conceitos fundamentais de arquivologia. 1.1 Natureza, finalidade e funções dos arquivos. 1.2 Princípios arquivísticos. 1.3 Classificação dos documentos quanto à natureza, espécie, gênero e suporte. Ciclo de vida dos documentos. 2.1 Teoria das três idades. 2.2 Arquivos correntes, intermediários e permanentes. Gestão documental. 3.1 Produção, recebimento, registro e tramitação de documentos. 3.2 Protocolo e controle documental. 3.3 Classificação e organização de documentos. 3.4 Métodos de arquivamento. 3.5 Avaliação e destinação documental. 3.6 Tabelas de temporalidade. Preservação e conservação de documentos. 4.1 Acondicionamento e armazenamento. 4.2 Medidas preventivas de conservação. Documentos digitais. 5.1 Conceitos e características. 5.2 Digitalização de documentos. 5.3 Sistemas informatizados de gestão arquivística de documentos. 5.4 Metadados e indexação documental. 5.5 Autenticidade, integridade e confiabilidade dos documentos. 5.6 Controle de versões e rastreabilidade documental. Gestão da informação arquivística. 6.1 Organização de acervos físicos e digitais. 6.2 Recuperação e localização de informações. 6.3 Controle de acesso a documentos. 6.4 Proteção de documentos sigilosos. 6.5 Compartilhamento e disponibilização de informações.'),
  ('Conhecimentos específicos', 'Tecnologia da Informação e Segurança da Informação', 4, 'Conceitos fundamentais de tecnologia da informação. 1.1 Sistemas de informação. 1.2 Processamento, armazenamento e transmissão de dados. 1.3 Dados estruturados e não estruturados. Sistemas operacionais e aplicativos. 2.1 Gerenciamento de arquivos e diretórios. 2.2 Formatos de arquivos digitais. 2.3 Compactação e descompactação de arquivos. Planilhas eletrônicas aplicadas à análise de dados. 3.1 Fórmulas e funções básicas e intermediárias. 3.2 Classificação, filtros e agrupamentos. 3.3 Tabelas dinâmicas e gráficos. 3.4 Importação e exportação de dados. 3.5 Tratamento de dados duplicados ou inconsistentes. Bancos de dados. 4.1 Conceitos fundamentais. 4.2 Tabelas, registros, campos, chaves e relacionamentos. 4.3 Consultas e filtros de dados. 4.4 Integração básica de informações provenientes de diferentes bases. Redes de computadores. 5.1 Conceitos de redes locais e internet. 5.2 Endereçamento IP. 5.3 Protocolos de comunicação. 5.4 Serviços de rede. Segurança da informação. 6.1 Confidencialidade, integridade e disponibilidade. 6.2 Controle de acesso e autenticação. 6.3 Criptografia: conceitos fundamentais. 6.4 Cópias de segurança. 6.5 Proteção de informações sensíveis. Metadados. 7.1 Conceitos e características. 7.2 Propriedades de arquivos digitais. 7.3 Informações de criação, modificação e armazenamento. Organização e tratamento de informações digitais. 8.1 Padronização e classificação de registros. 8.2 Identificação de duplicidades. 8.3 Cruzamento de informações em planilhas. 8.4 Construção de tabelas e gráficos para apresentação de resultados.'),
  ('Conhecimentos específicos', 'Análise de Dados e Informações', 5, 'Conceitos fundamentais de dados, informação e conhecimento. 1.1 Dados estruturados, semiestruturados e não estruturados. 1.2 Fontes de informação. 1.3 Critérios de confiabilidade e qualidade das informações. Organização e tratamento de dados. 2.1 Coleta e classificação de informações. 2.2 Padronização de registros. 2.3 Identificação de duplicidades e inconsistências. 2.4 Tratamento de dados incompletos. 2.5 Organização de conjuntos de dados em tabelas e planilhas. Cruzamento e comparação de informações. 3.1 Identificação de correspondências entre registros. 3.2 Comparação de dados provenientes de diferentes fontes. 3.3 Identificação de padrões, recorrências e divergências. 3.4 Análise de relações entre registros. Análise temporal. 4.1 Organização cronológica de eventos. 4.2 Construção e interpretação de linhas do tempo. 4.3 Identificação de intervalos e sequências temporais. 4.4 Comparação de registros por data e horário. Análise de vínculos. 5.1 Identificação de relações entre pessoas, organizações, endereços e registros. 5.2 Construção e interpretação de diagramas de vínculos. 5.3 Identificação de conexões diretas e indiretas. 5.4 Análise de redes de relacionamento em conjuntos de dados. Análise de registros de comunicação. 6.1 Organização de registros em tabelas. 6.2 Identificação de frequência, duração e sequência de comunicações. 6.3 Comparação de registros de contatos e horários. 6.4 Identificação de padrões de comunicação. Análise geográfica básica. 7.1 Localização e distribuição espacial de eventos. 7.2 Interpretação de coordenadas geográficas. 7.3 Comparação de distâncias e trajetos. 7.4 Representação de informações em mapas. Métodos de análise de informações. 8.1 Identificação de fatos, inferências e hipóteses. 8.2 Formulação e comparação de hipóteses explicativas. 8.3 Identificação de contradições e lacunas informacionais. 8.4 Avaliação da consistência de informações. 8.5 Distinção entre correlação e causalidade. Produção de informações analíticas. 9.1 Elaboração de quadros demonstrativos. 9.2 Construção de tabelas, gráficos e diagramas. 9.3 Sistematização e síntese de informações. 9.4 Elaboração de relatórios informativos e analíticos. 9.5 Apresentação objetiva de resultados e conclusões. 9.6 Indicação de limitações e insuficiências dos dados analisados. Proteção e qualidade das informações. 10.1 Confidencialidade e controle de acesso. 10.2 Integridade e rastreabilidade de registros. 10.3 Identificação de erros e inconsistências em bases de dados.'),
  ('Conhecimentos específicos', 'Noções de Administração', 6, 'Conceitos e princípios gerais da administração. 1.1 Funções administrativas: planejamento, organização, direção e controle. 1.2 Eficiência, eficácia e efetividade. Estruturas organizacionais. 2.1 Organização e divisão do trabalho. 2.2 Comunicação organizacional. 2.3 Trabalho em equipe e relações interpessoais. Gestão de processos. 3.1 Organização e padronização de rotinas de trabalho. 3.2 Planejamento e controle de atividades. 3.3 Gestão do tempo e definição de prioridades. 3.4 Melhoria contínua de processos. Gestão da informação e do conhecimento. 4.1 Organização, armazenamento e compartilhamento de informações. 4.2 Fluxos de informação nas organizações. 4.3 Gestão de documentos e registros administrativos. Administração de recursos materiais. 5.1 Controle e organização de materiais. 5.2 Noções de gestão patrimonial. Qualidade no atendimento. 6.1 Atendimento ao público. 6.2 Comunicação clara e objetiva. 6.3 Ética e comportamento profissional. 6.4 Responsabilidade e sigilo no tratamento de informações.')
)
insert into public.syllabus_topics (edition_id, block_name, discipline, topic_order, topic_text)
select edition.id, topics.block_name, topics.discipline, topics.topic_order, topics.topic_text
from edition cross join topics
where not exists (
  select 1 from public.syllabus_topics t
  where t.edition_id=edition.id and t.discipline=topics.discipline and t.topic_order=topics.topic_order
);

